"""
    Julian_Epoch_to_MJD(jepoch):
       Convert Julian Epoch to Modified Julian Date (MJD)
    """
def Julian_Epoch_to_MJD(jepoch: Any) -> object {
    return (51544.5 + ((jepoch - 2000.0) * 365.25));
}

test_blocks:
test "t0" {
    assert (Julian_Epoch_to_MJD(2000.5) == (51544.5 + (365.25 / 2)));;
}

test "t1" {
    assert (Julian_Epoch_to_MJD(2000) == 51544.5);;
}

test "t2" {
    assert (Julian_Epoch_to_MJD(2000.0) == 51544.5);;
}

test "t3" {
    assert (Julian_Epoch_to_MJD(2010) == 55197.0);;
}
